def hungarian_algorithm(cost_matrix):
    for i in range(len(cost_matrix)):
        min_val = min(cost_matrix[i])
        cost_matrix[i] = [x - min_val for x in cost_matrix[i]]
    for j in range(len(cost_matrix[0])):
        min_val = min([row[j] for row in cost_matrix])
        for i in range(len(cost_matrix)):
            cost_matrix[i][j] -= min_val
    lines = cover_zeros(cost_matrix)
    if not is_solution(cost_matrix, lines):
        return find_solution(cost_matrix, lines)
    else:
        return calculate_solution(cost_matrix, lines)

