    half_sum = total_sum // 2
    dp = [[False] * (half_sum + 1) for _ in range(len(weights) + 1)]
    dp[0][0] = True

    for i in range(1, len(weights) + 1):
        for j in range(half_sum + 1):
            if j < weights[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - weights[i - 1]]

    for j in range(half_sum, -1, -1):
        if dp[-1][j]:
            return abs(total_sum - 2 * j)

    return 0

